The macro FAN_FROM_REG evaluates its arguments multiple times. When used
in lockless contexts involving shared driver data, this leads to
Time-of-Check to Time-of-Use (TOCTOU) race conditions, potentially
causing divide-by-zero errors.

Convert the macro to a static function. This guarantees that arguments
are evaluated only once (pass-by-value), preventing the race
conditions.

Additionally, in store_fan_div, move the calculation of the minimum
limit inside the update lock. This ensures that the read-modify-write
sequence operates on consistent data.

Adhere to the principle of minimal changes by only converting macros
that evaluate arguments multiple times and are used in lockless
contexts.

Link: https://lore.kernel.org/all/CALbr=LYJ_ehtp53HXEVkSpYoub+XYSTU8Rg=o1xxMJ8=5z8B-g@mail.gmail.com/
Fixes: 9873964d6eb2 ("[PATCH] HWMON: w83791d: New hardware monitoring driver for the Winbond W83791D")
Cc: stable@vger.kernel.org
Signed-off-by: Gui-Dong Han <hanguidong02@gmail.com>
Link: https://lore.kernel.org/r/20251202180105.12842-1-hanguidong02@gmail.com
Signed-off-by: Guenter Roeck <linux@roeck-us.net>

Here is the root cause:
The macro `FAN_FROM_REG` evaluated its arguments multiple times, causing a Time-of-Check to Time-of-Use (TOCTOU) race condition when used in lockless contexts with shared driver data. Additionally, in `store_fan_div`, the calculation of the fan minimum limit was performed outside the `update_lock` mutex, allowing another thread to modify `data->fan_min` or `data->fan_div` between the read and the lock acquisition, leading to inconsistent data and potential divide-by-zero errors.

Here is the patch:
 }

-#define FAN_FROM_REG(val, div)	((val) == 0 ? -1 : \
-				((val) == 255 ? 0 : \
-					1350000 / ((val) * (div))))
+static int fan_from_reg(int val, int div)
+{
+	if (val == 0)
+		return -1;
+	if (val == 255)
+		return 0;
+	return 1350000 / (val * div);
+}

 /* for temp1 which is 8-bit resolution, LSB = 1 degree Celsius */
 	int nr = sensor_attr->index; \
 	return sprintf(buf, "%d\n", \
-		FAN_FROM_REG(data->reg[nr], DIV_FROM_REG(data->fan_div[nr]))); \
+		fan_from_reg(data->reg[nr], DIV_FROM_REG(data->fan_div[nr]))); \
 }

  */
 static ssize_t store_fan_div(struct device *dev, struct device_attribute *attr,
 				const char *buf, size_t count)
 {
 	struct sensor_device_attribute *sensor_attr = to_sensor_dev_attr(attr);
 	struct i2c_client *client = to_i2c_client(dev);
 	struct w83791d_data *data = i2c_get_clientdata(client);
 	int nr = sensor_attr->index;
 	unsigned long min;
 	u8 tmp_fan_div;
 	u8 fan_div_reg;
 	u8 vbat_reg;
 	int indx = 0;
 	u8 keep_mask = 0;
 	u8 new_shift = 0;
 	unsigned long val;
 	int err;

 	err = kstrtoul(buf, 10, &val);
 	if (err)
 		return err;

+	mutex_lock(&data->update_lock);
 	/* Save fan_min */
-	min = FAN_FROM_REG(data->fan_min[nr], DIV_FROM_REG(data->fan_div[nr]));
+	min = fan_from_reg(data->fan_min[nr], DIV_FROM_REG(data->fan_div[nr]));

-	mutex_lock(&data->update_lock);
 	data->fan_div[nr] = div_to_reg(nr, val);

 	switch (nr) {
 	case 0:
 		indx = 0;
 		keep_mask = 0xcf;
 		new_shift = 4;
 		break;
 	case 1:
 		indx = 0;
 		keep_mask = 0x3f;
 		new_shift = 6;
 		break;
 	case 2:
 		indx = 1;
 		keep_mask = 0x3f;
 		new_shift = 6;
 		break;
 	case 3:
 		indx = 2;
 		keep_mask = 0xf8;
 		new_shift = 0;
 		break;
 	case 4:
 		indx = 2;
 		keep_mask = 0x8f;
 		new_shift = 4;
 		break;
 #ifdef DEBUG
 	default:
 		dev_warn(dev, "store_fan_div: Unexpected nr seen: %d\n", nr);
 		count = -EINVAL;
 		goto err_exit;
 #endif
 	}

 	fan_div_reg = w83791d_read(client, W83791D_REG_FAN_DIV[indx])
 			& keep_mask;
 	tmp_fan_div = (data->fan_div[nr] << new_shift) & ~keep_mask;

 	w83791d_write(client, W83791D_REG_FAN_DIV[indx],
 				fan_div_reg | tmp_fan_div);

 	/* Bit 2 of fans 0-2 is stored in the vbat register (bits 5-7) */
 	if (nr < 3) {
 		keep_mask = ~(1 << (nr + 5));
 		vbat_reg = w83791d_read(client, W83791D_REG_VBAT)
 				& keep_mask;
 		tmp_fan_div = (data->fan_div[nr] << (3 + nr)) & ~keep_mask;
 		w83791d_write(client, W83791D_REG_VBAT,
 				vbat_reg | tmp_fan_div);
 	}

 	/* Restore fan_min */
 	data->fan_min[nr] = fan_to_reg(min, DIV_FROM_REG(data->fan_div[nr]));
 	w83791d_write(client, W83791D_REG_FAN_MIN[nr], data->fan_min[nr]);

 #ifdef DEBUG
 err_exit:
 #endif
 	mutex_unlock(&data->update_lock);

 	return count;
 }



